    foreach(['verified_unknown'=>'student_directory_access_denied','verified_duplicate'=>'student_email_ambiguous','verified_mismatch'=>'student_email_mismatch','verified_domain'=>'email_domain_denied']as$scenario=>$reason){$r=$request($scenario);$issues=$header($r,'X-QA-Issues')??[];$check($r['status']===403&&($r['data']['reason']??'')===$reason,'Identity failures reject the login: '.$scenario);$check(count($issues)===1&&(int)$issues[0]['identity_verified']===1&&$issues[0]['failure_code']===$reason,'Verified failures retain the entered email, Google email and reason: '.$scenario);}
    $r=$request('verified_unverified');$check($r['status']===403&&count($header($r,'X-QA-Issues')??[])===0,'Unverified claims are not recorded as a Google-verified identity.');
