    foreach(['start_unknown'=>'student_directory_access_denied','start_duplicate'=>'student_email_ambiguous']as$scenario=>$reason){$r=$request($scenario);$issues=$header($r,'X-QA-Issues')??[];$check($r['status']===302&&strpos($r['headers'],$reason)!==false&&count($issues)===1&&(int)$issues[0]['identity_verified']===0,'Unmatched and duplicated entered emails are retained before opening Google: '.$scenario);}
