    $r=$request('start_success');$pending=$header($r,'X-QA-OAuth-Pending');$check($r['status']===302&&strpos($r['headers'],'Location: https://accounts.google.com/')!==false&&strpos($r['headers'],'login_hint=')!==false&&$pending['student']===true,'Student Google sign-in starts with a bound state, nonce and email hint.');
