    $r=$request('admin_review');$issues=$header($r,'X-QA-Issues')??[];$check($r['status']===302&&count(array_filter($issues,static function($row){return $row['review_status']==='reviewed';}))===1&&strpos($r['headers'],'X-QA-Protected-Unchanged: yes')!==false,'Reviewing an issue stores a note without changing student records.');
    $r=$request('admin_repeat');$issues=$header($r,'X-QA-Issues')??[];$grouped=array_values(array_filter($issues,static function($row){return $row['identity_verified'];}));$check($r['status']===200&&count($grouped)===1&&(int)$grouped[0]['attempt_count']===3&&$grouped[0]['review_status']==='open'&&$grouped[0]['review_note']==='Previously checked.','Repeated failures are grouped and reopen a reviewed issue while retaining its note.');
